sys_variable_value.value:
(function execute(inputs, outputs) {

var currentRecord = inputs.currentRecord;
var errorMessages = [];

var companyCode = currentRecord.variables.company_code 
    ? currentRecord.variables.company_code.getDisplayValue() 
    : '';
var contractNumber = currentRecord.variables.local_luc 
    ? currentRecord.variables.local_luc.getDisplayValue() 
    : 'Campo Vazio';
var dataDistrato = currentRecord.variables.data_de_distrato 
    ? currentRecord.variables.data_de_distrato.getDisplayValue() 
    : '';

var dataDistratoFormatado = '';
var companyAnswer = '';
var contractNumberAnswer = '';
outputs.errorcampovazio = contractNumber;

if(companyCode){
  companyAnswer = companyCode;
} else {
  companyAnswer = 'Não há';
  errorMessages.push('Campo Código da Empresa vazio detectado');
}

if(contractNumber){
  contractNumberAnswer = contractNumber;
} else {
  contractNumberAnswer = 'Não há';
  errorMessages.push('Campo Contrato vazio detectado');
}

if(dataDistrato){
  dataDistratoFormatado = formatDateToYYYYMMDD(dataDistrato);
} else {
  dataDistratoFormatado = 'Não há';
  errorMessages.push('Campo Data de Desligamento vazio detectado');
}

var myObj = {
  "CompanyCode": companyAnswer,
  "ContractNumber": contractNumberAnswer,
  "NoticeDate": dataDistratoFormatado,
  "NoticeReceiptDate": dataDistratoFormatado,
};

var teste = '';

if(errorMessages.length > 0) {
  outputs.erroranswer = errorMessages.join(' | ');
}

gs.info(JSON.stringify(myObj));
outputs.myobj = JSON.stringify(myObj);

function formatDateToYYYYMMDD(dateString) {
    var parts = dateString.split('/');
    var day = parts[0];
    var month = parts[1];
    var year = parts[2];
    return year + '-' + month + '-' + day;
}

})(inputs, outputs);

